package dev.industrialtechnology.test;
import java.util.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
import cpw.mods.fml.common.*;import cpw.mods.fml.common.event.*;import cpw.mods.fml.common.eventhandler.*;import cpw.mods.fml.common.gameevent.TickEvent;import cpw.mods.fml.common.registry.GameRegistry;
import dev.industrialtechnology.core.*;import dev.industrialtechnology.accessories.*;import baubles.api.*;import baubles.common.lib.PlayerHandler;
import net.minecraft.world.*;import net.minecraft.server.MinecraftServer;import net.minecraft.entity.player.*;import net.minecraft.entity.passive.EntityPig;import net.minecraft.item.*;import net.minecraft.init.*;import net.minecraft.inventory.*;import net.minecraft.potion.*;import net.minecraft.nbt.*;import net.minecraft.util.*;import net.minecraft.item.crafting.*;import net.minecraftforge.common.*;import net.minecraftforge.common.util.FakePlayer;import net.minecraftforge.event.world.BlockEvent;
@Mod(modid="industrialtech_accessory_checks",name="Disposable accessories checks",version="1",dependencies="required-after:industrialtech")
public final class AccessoryServerChecks {
 private final List<String> report=new ArrayList<String>();private int ticks,failed;private boolean done;private WorldServer w;private FakePlayer p;private String stage="initial";
 interface Check{void run()throws Exception;}static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}void test(String name,Check c){try{c.run();report.add("PASS: "+name);}catch(Throwable e){failed++;report.add("FAIL: "+name+" :: "+e);IndustrialTechnology.log.error(name,e);}}
 @Mod.EventHandler public void init(FMLInitializationEvent e){if(Boolean.getBoolean("industrialtech.accessoryTest"))FMLCommonHandler.instance().bus().register(this);}
 private void clear(){for(int i=0;i<p.inventory.getSizeInventory();i++)p.inventory.setInventorySlotContents(i,null);p.inventory.currentItem=0;p.capabilities.isCreativeMode=false;}
 private ItemStack tool(Item item,int charge){ItemStack s=new ItemStack(item);NBTTagCompound n=new NBTTagCompound();n.setByte("Charge",(byte)charge);s.setTagCompound(n);return s;}
 private ItemStack craft(ItemStack... grid){InventoryCrafting inv=new InventoryCrafting(new Container(){public boolean canInteractWith(EntityPlayer p){return true;}},3,3);for(int i=0;i<grid.length;i++)inv.setInventorySlotContents(i,grid[i]);return CraftingManager.getInstance().findMatchingRecipe(inv,w);}
 private ItemStack s(Item i){return new ItemStack(i);}private ItemStack s(net.minecraft.block.Block b){return new ItemStack(b);}private int amount(List<ItemStack> list){int count=0;for(ItemStack s:list)count+=s.stackSize;return count;}
 public static final class DenyBreak {@SubscribeEvent public void deny(BlockEvent.BreakEvent e){if(e.x==45&&e.z==45)e.setCanceled(true);}}
 private void clearWearables(){IInventory inv=PlayerHandler.getPlayerBaubles(p);for(int i=0;i<inv.getSizeInventory();i++)inv.setInventorySlotContents(i,null);clear();p.theItemInWorldManager.setGameType(WorldSettings.GameType.SURVIVAL);}
 private boolean useHeld(){return p.theItemInWorldManager.tryUseItem(p,w,p.getHeldItem());}
 private void checks(){
  test("Survival right-click amulet goes through vanilla ItemInWorldManager without a null return",()->{clearWearables();ItemStack held=s(AccessoryRegistry.nightAmulet);held.setStackDisplayName("Right-click regression");p.inventory.setInventorySlotContents(0,held);check(useHeld(),"Vanilla did not consume held stack");ItemStack equipped=PlayerHandler.getPlayerBaubles(p).getStackInSlot(0);check(p.getHeldItem()==null&&held.stackSize==0&&equipped!=held&&equipped.stackSize==1&&equipped.getDisplayName().equals("Right-click regression"),"Equip/consumption/NBT");});
  test("Survival right-click rings fill both slots and a third ring stays in hand",()->{clearWearables();IInventory inv=PlayerHandler.getPlayerBaubles(p);for(int slot=1;slot<=2;slot++){p.inventory.setInventorySlotContents(0,s(AccessoryRegistry.flightRing));check(useHeld()&&p.getHeldItem()==null&&inv.getStackInSlot(slot).stackSize==1&&p.capabilities.allowFlying,"Ring equip "+slot);}ItemStack third=s(AccessoryRegistry.flightRing);p.inventory.setInventorySlotContents(0,third);check(!useHeld()&&p.getHeldItem()==third&&third.stackSize==1,"Full ring slots consumed held ring");});
  test("Right-click with an occupied amulet slot preserves both items",()->{clearWearables();IInventory inv=PlayerHandler.getPlayerBaubles(p);ItemStack worn=s(AccessoryRegistry.nightAmulet);inv.setInventorySlotContents(0,worn);ItemStack held=s(AccessoryRegistry.nightAmulet);p.inventory.setInventorySlotContents(0,held);check(!useHeld()&&p.getHeldItem()==held&&held.stackSize==1&&inv.getStackInSlot(0)==worn,"Occupied slot overwritten");});
  test("Creative right-click equips amulet and ring while retaining held items",()->{clearWearables();try{p.theItemInWorldManager.setGameType(WorldSettings.GameType.CREATIVE);for(Item item:new Item[]{AccessoryRegistry.nightAmulet,AccessoryRegistry.flightRing}){ItemStack held=s(item);p.inventory.setInventorySlotContents(0,held);useHeld();check(p.getHeldItem()==held&&held.stackSize==1,"Creative held item lost");}IInventory inv=PlayerHandler.getPlayerBaubles(p);check(inv.getStackInSlot(0).getItem()==AccessoryRegistry.nightAmulet&&inv.getStackInSlot(1).getItem()==AccessoryRegistry.flightRing,"Creative equipment missing");}finally{clearWearables();}});

  test("Standalone content loads without requiring ProjectE or Baublelicious",()->{for(Item item:new Item[]{AccessoryRegistry.flightRing,AccessoryRegistry.nightAmulet,AccessoryRegistry.catalyst,AccessoryRegistry.hyperLens,AccessoryRegistry.catalyticLens})check(item!=null&&item.getItemStackLimit(new ItemStack(item))==1,"Missing/nonunique item");report.add("INFO: original mods present="+Loader.isModLoaded("ProjectE")+","+Loader.isModLoaded("baublelicious"));});
  test("Alternative Destruction Catalyst recipe uses only ordinary materials",()->{ItemStack out=craft(s(Items.glowstone_dust),s(Blocks.obsidian),s(Items.glowstone_dust),s(Blocks.redstone_block),s(Items.diamond),s(Blocks.redstone_block),s(Items.glowstone_dust),s(Blocks.obsidian),s(Items.glowstone_dust));check(out!=null&&out.getItem()==AccessoryRegistry.catalyst,"Wrong catalyst recipe");});
  test("Alternative Hyperkinetic Lens recipe uses only ordinary materials",()->{ItemStack out=craft(s(Blocks.glass),s(Items.quartz),s(Blocks.glass),s(Items.diamond),s(Items.ender_pearl),s(Items.diamond),s(Blocks.glass),s(Items.quartz),s(Blocks.glass));check(out!=null&&out.getItem()==AccessoryRegistry.hyperLens,"Wrong lens recipe");});
  test("Alternative Catalytic Lens recipe combines our two tools and vanilla materials",()->{ItemStack out=craft(s(Items.diamond),s(Items.nether_star),s(Items.diamond),s(AccessoryRegistry.hyperLens),s(Blocks.redstone_block),s(AccessoryRegistry.catalyst),s(Items.diamond),s(Items.nether_star),s(Items.diamond));check(out!=null&&out.getItem()==AccessoryRegistry.catalyticLens,"Wrong catalytic recipe");});
  test("Flight and nightvision original accessory recipes have standalone base/core ingredients",()->{ItemStack out=craft(null,new ItemStack(AccessoryRegistry.core,1,2),null,s(Items.feather),s(AccessoryRegistry.ring),s(Items.feather),null,s(Items.diamond),null);check(out!=null&&out.getItem()==AccessoryRegistry.flightRing,"Flight recipe");out=craft(null,new ItemStack(AccessoryRegistry.core,1,1),null,s(Items.golden_carrot),s(AccessoryRegistry.amulet),s(Items.golden_carrot),null,new ItemStack(Items.potionitem,1,8198),null);check(out!=null&&out.getItem()==AccessoryRegistry.nightAmulet,"Night recipe");});
  test("Real Baubles slots accept rings/amulets and reject incorrect equipment types",()->{IInventory inv=PlayerHandler.getPlayerBaubles(p);check(inv.getSizeInventory()==4&&inv.isItemValidForSlot(1,s(AccessoryRegistry.flightRing))&&inv.isItemValidForSlot(2,s(AccessoryRegistry.flightRing))&&!inv.isItemValidForSlot(0,s(AccessoryRegistry.flightRing))&&inv.isItemValidForSlot(0,s(AccessoryRegistry.nightAmulet)),"Slot mapping");});
  test("Survival flight grants creative-style flight and removes it on unequip",()->{p.capabilities.allowFlying=false;ItemStack ring=s(AccessoryRegistry.flightRing);((IBauble)ring.getItem()).onEquipped(ring,p);check(p.capabilities.allowFlying,"No flight");p.capabilities.isFlying=true;((IBauble)ring.getItem()).onUnequipped(ring,p);check(!p.capabilities.allowFlying&&!p.capabilities.isFlying,"Flight stayed on");});
  test("Flight ring does not revoke Creative flight",()->{p.capabilities.isCreativeMode=true;p.capabilities.allowFlying=true;ItemStack ring=s(AccessoryRegistry.flightRing);((IBauble)ring.getItem()).onUnequipped(ring,p);check(p.capabilities.allowFlying,"Creative flight revoked");p.capabilities.isCreativeMode=false;});
  test("A second worn flight ring continues granting flight",()->{IInventory inv=PlayerHandler.getPlayerBaubles(p);ItemStack other=s(AccessoryRegistry.flightRing);inv.setInventorySlotContents(2,other);p.capabilities.allowFlying=true;((IBauble)AccessoryRegistry.flightRing).onUnequipped(s(AccessoryRegistry.flightRing),p);check(p.capabilities.allowFlying,"Second ring ignored");inv.setInventorySlotContents(2,null);});
  test("Nightvision uses original strength/duration, refreshes and removes on unequip",()->{IBauble a=(IBauble)AccessoryRegistry.nightAmulet;ItemStack s=s(AccessoryRegistry.nightAmulet);a.onWornTick(s,p);PotionEffect e=p.getActivePotionEffect(Potion.nightVision);check(e!=null&&e.getDuration()==999999&&e.getAmplifier()==1,"Nightvision effect");p.removePotionEffect(Potion.nightVision.id);p.addPotionEffect(new PotionEffect(Potion.nightVision.id,50,1));a.onWornTick(s,p);check(p.getActivePotionEffect(Potion.nightVision).getDuration()==999999,"Refresh");a.onUnequipped(s,p);check(!p.isPotionActive(Potion.nightVision),"Effect remains");});
  test("Coal fuel accepts coal, charcoal and coal blocks",()->check(CoalFuel.value(s(Items.coal))==128&&CoalFuel.value(new ItemStack(Items.coal,1,1))==32&&CoalFuel.value(s(Blocks.coal_block))==1152,"Coal equivalents"));
  test("Wood, sticks, saplings, lava, blaze and redstone cannot fuel the tools",()->{for(ItemStack fuel:new ItemStack[]{s(Blocks.log),s(Blocks.log2),s(Blocks.planks),s(Blocks.sapling),s(Items.stick),s(Items.lava_bucket),s(Items.blaze_rod),s(Items.redstone),s(Items.gunpowder)})check(CoalFuel.value(fuel)==0,"Forbidden fuel "+fuel);});
  if(Loader.isModLoaded("hbm"))test("All HBM Coal/Lignite/Petroleum Coke variants are accepted",()->{Item coke=(Item)Class.forName("com.hbm.items.ModItems").getField("coke").get(null);check(coke!=null,"HBM coke registry");for(int meta=0;meta<3;meta++)check(CoalFuel.value(new ItemStack(coke,1,meta))>0,"Coke meta "+meta);});
  test("Fuel scans the full player inventory and preserves paid change",()->{clear();p.inventory.setInventorySlotContents(35,s(Items.coal));ItemStack t=s(AccessoryRegistry.catalyst);check(CoalFuel.consume(p,t,8)&&p.inventory.getStackInSlot(35)==null&&CoalFuel.stored(t)==120,"Fuel/change");check(CoalFuel.consume(p,t,8)&&CoalFuel.stored(t)==112,"Stored fuel");});
  test("Insufficient coal is atomic and never consumes wood or partial coal",()->{clear();p.inventory.setInventorySlotContents(3,s(Items.coal));p.inventory.setInventorySlotContents(4,new ItemStack(Blocks.log,64));ItemStack t=s(AccessoryRegistry.hyperLens);check(!CoalFuel.consume(p,t,384)&&p.inventory.getStackInSlot(3).stackSize==1&&p.inventory.getStackInSlot(4).stackSize==64,"Partial fuel lost");});
  test("Original charge limits, mining depths and projectile costs are retained",()->{ItemCatalyst c=(ItemCatalyst)AccessoryRegistry.catalyst,l=(ItemCatalyst)AccessoryRegistry.catalyticLens;int[] depths={1,4,8,16};for(int i=0;i<4;i++)check(c.depth(tool(c,i))==depths[i],"Depth "+i);check(l.depth(tool(l,7))==64&&ItemCatalyst.SHOT_COST[0]==384&&ItemCatalyst.SHOT_COST[3]==2304&&ItemCatalyst.SHOT_RADIUS[7]==16,"Lens tables");ItemStack t=tool(c,127);check(c.charge(t)==3,"NBT charge bounds");});
  test("Charge controls increase/decrease and preserve fuel NBT",()->{ItemStack t=tool(AccessoryRegistry.catalyst,0);t.getTagCompound().setDouble("StoredEMC",55);ItemCatalyst c=(ItemCatalyst)t.getItem();p.setSneaking(false);c.changeCharge(p,t);check(c.charge(t)==1,"Charge up");p.setSneaking(true);c.changeCharge(p,t);p.setSneaking(false);check(c.charge(t)==0&&CoalFuel.stored(t)==55,"Charge down/data");});
  test("All six mining directions produce the original 3x3xdepth box",()->{for(int side=0;side<6;side++){AxisAlignedBB b=AccessoryWorld.box(4,80,4,side,16);check((b.maxX-b.minX+1)*(b.maxY-b.minY+1)*(b.maxZ-b.minZ+1)==144,"Box side "+side);}});
  test("Real catalyst mines nine blocks, skips bedrock/obsidian and creates collected loot",()->{clear();p.inventory.setInventorySlotContents(35,s(Items.coal));for(int x=39;x<=41;x++)for(int y=79;y<=81;y++)w.setBlock(x,y,40,Blocks.stone,0,3);w.setBlock(39,79,40,Blocks.bedrock,0,3);w.setBlock(41,81,40,Blocks.obsidian,0,3);ItemStack t=tool(AccessoryRegistry.catalyst,0);p.inventory.setInventorySlotContents(0,t);AccessoryWorld.mine(p,t,new MovingObjectPosition(40,80,40,2,Vec3.createVectorHelper(40,80,40)),1);check(w.isAirBlock(40,80,40)&&w.getBlock(39,79,40)==Blocks.bedrock&&w.getBlock(41,81,40)==Blocks.obsidian&&CoalFuel.stored(t)==72,"Mine/fuel/hardness");List balls=w.getEntitiesWithinAABB(EntityLootBall.class,AxisAlignedBB.getBoundingBox(38,78,38,43,83,43));check(balls.size()==1&&amount(((EntityLootBall)balls.get(0)).contents())==7,"Collected drops");});
  test("Forge break cancellation prevents mining protected blocks",()->{Object deny=new DenyBreak();MinecraftForge.EVENT_BUS.register(deny);try{p.capabilities.isCreativeMode=true;w.setBlock(45,80,45,Blocks.stone,0,3);AccessoryWorld.mine(p,tool(AccessoryRegistry.catalyst,0),new MovingObjectPosition(45,80,45,2,Vec3.createVectorHelper(45,80,45)),1);check(w.getBlock(45,80,45)==Blocks.stone,"Protection bypass");}finally{MinecraftForge.EVENT_BUS.unregister(deny);p.capabilities.isCreativeMode=false;}});
  test("Loot survives NBT and partial inventory pickup without loss/duplication",()->{clear();for(int i=0;i<36;i++)p.inventory.setInventorySlotContents(i,new ItemStack(Blocks.dirt,64));p.inventory.setInventorySlotContents(0,new ItemStack(Blocks.cobblestone,60));EntityLootBall b=new EntityLootBall(w,new ArrayList<ItemStack>(Arrays.asList(new ItemStack(Blocks.cobblestone,20))),60,80,60);b.onCollideWithPlayer(p);check(p.inventory.getStackInSlot(0).stackSize==64&&amount(b.contents())==16&&!b.isDead,"Partial pickup");NBTTagCompound n=new NBTTagCompound();b.writeToNBT(n);EntityLootBall copy=new EntityLootBall(w);copy.readFromNBT(n);check(amount(copy.contents())==16,"Loot save");p.inventory.setInventorySlotContents(1,null);copy.onCollideWithPlayer(p);check(copy.isDead&&p.inventory.getStackInSlot(1).stackSize==16,"Remaining pickup");});
  test("Original nova blast destroys blocks and collects drops without damaging entities",()->{p.capabilities.isCreativeMode=false;for(int x=69;x<=71;x++)for(int y=79;y<=81;y++)for(int z=69;z<=71;z++)w.setBlock(x,y,z,Blocks.stone,0,3);EntityPig pig=new EntityPig(w);pig.setPosition(70,82,70);w.spawnEntityInWorld(pig);float hp=pig.getHealth();AccessoryWorld.nova(w,p,70,80,70,4);check(w.isAirBlock(70,80,70)&&pig.getHealth()==hp,"Nova behavior");});
  test("Actual lens firing pays the original projectile cost and refuses wood",()->{clear();ItemStack t=tool(AccessoryRegistry.hyperLens,0);p.inventory.setInventorySlotContents(0,t);p.inventory.setInventorySlotContents(35,new ItemStack(Items.coal,3));check(((ItemCatalyst)t.getItem()).shoot(p,t)&&p.inventory.getStackInSlot(35)==null&&CoalFuel.stored(t)==0,"Shot fuel");p.inventory.setInventorySlotContents(35,new ItemStack(Blocks.log,64));check(!((ItemCatalyst)t.getItem()).shoot(p,t)&&p.inventory.getStackInSlot(35).stackSize==64,"Wood shot");});
  test("Saved world keeps charged tools and stored coal credit",()->{w.setBlock(20,80,20,Blocks.chest,0,3);ItemStack t=tool(AccessoryRegistry.catalyticLens,6);t.getTagCompound().setDouble("StoredEMC",777);((IInventory)w.getTileEntity(20,80,20)).setInventorySlotContents(0,t);IInventory worn=PlayerHandler.getPlayerBaubles(p);worn.setInventorySlotContents(0,new ItemStack(AccessoryRegistry.nightAmulet));worn.setInventorySlotContents(1,new ItemStack(AccessoryRegistry.flightRing));PlayerHandler.savePlayerBaubles(p,new File("baubles-player.dat"),new File("baubles-player.dat.bak"));check(new File("baubles-player.dat").isFile(),"Baubles save missing");w.saveAllChunks(true,null);Files.write(Paths.get("accessories-saved.done"),Arrays.asList("saved"),StandardCharsets.UTF_8);});
 }
 @SubscribeEvent public void tick(TickEvent.ServerTickEvent e){if(done||e.phase!=TickEvent.Phase.END||!MinecraftServer.getServer().isDedicatedServer()||++ticks!=20)return;try{w=MinecraftServer.getServer().worldServerForDimension(0);p=new FakePlayer(w,new com.mojang.authlib.GameProfile(UUID.fromString("2424a054-5e1a-4bb2-83de-710b3900f0d9"),"AccessoriesQA")){public void sendPlayerAbilities(){}public void addChatMessage(IChatComponent m){}};p.playerNetServerHandler=new net.minecraft.network.NetHandlerPlayServer(MinecraftServer.getServer(),new net.minecraft.network.NetworkManager(false),p){@Override public void sendPacket(net.minecraft.network.Packet packet){}};p.theItemInWorldManager.setGameType(WorldSettings.GameType.SURVIVAL);p.setPosition(40,80,37);for(int x=0;x<6;x++)for(int z=0;z<6;z++)w.getChunkFromChunkCoords(x,z);if(new File("accessories-saved.done").exists()){stage="restart";test("Charged standalone tool and coal credit survive a genuine JVM restart",()->{ItemStack t=((IInventory)w.getTileEntity(20,80,20)).getStackInSlot(0);check(t.getItem()==AccessoryRegistry.catalyticLens&&((ItemCatalyst)t.getItem()).charge(t)==6&&CoalFuel.stored(t)==777,"World persistence");PlayerHandler.loadPlayerBaubles(p,new File("baubles-player.dat"),new File("baubles-player.dat.bak"));IInventory worn=PlayerHandler.getPlayerBaubles(p);check(worn.getStackInSlot(0).getItem()==AccessoryRegistry.nightAmulet&&worn.getStackInSlot(1).getItem()==AccessoryRegistry.flightRing,"Baubles persistence");p.capabilities.allowFlying=false;((IBauble)AccessoryRegistry.flightRing).onWornTick(worn.getStackInSlot(1),p);((IBauble)AccessoryRegistry.nightAmulet).onWornTick(worn.getStackInSlot(0),p);check(p.capabilities.allowFlying&&p.isPotionActive(Potion.nightVision),"Reload effects");});}else checks();}catch(Throwable t){failed++;report.add("FAIL: setup :: "+t);IndustrialTechnology.log.error("Accessory tests",t);}finally{done=true;report.add("Failed: "+failed);try{Files.write(Paths.get("accessories-"+stage+".txt"),report,StandardCharsets.UTF_8);}catch(Exception ex){throw new RuntimeException(ex);}MinecraftServer.getServer().initiateShutdown();}}
}
